module TopModule(
   input   clk,
   input   rst_n,

   output  reg [3:0] gray_out
);
//Gray code to binary conversion
reg  [3:0] bin_out;
wire [3:0] gray_wire;

always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      bin_out <= 4'b0;
   end
   else begin
      bin_out[3] <= gray_wire[3];
      bin_out[2] <= gray_wire[2]^bin_out[3];
      bin_out[1] <= gray_wire[1]^bin_out[2];
      bin_out[0] <= gray_wire[0]^bin_out[1];
   end 
end
//Binary increment with 2-cycle counter
reg [3:0] count;
always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      count <= 4'b0;
   end
   else begin
      count <= count + 1'b1;
   end
end
//Binary to gray code conversion
assign gray_wire = (count >> 1) ^ count;

always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      gray_out <= 4'b0;
   end
   else begin
      if (count[0]) gray_out <= gray_wire;
   end
end
endmodule

